// تصنيف الآلية لعمود التقرير الأسبوعي (وإلا: أخرى)
function weeklyColOf(v) {
  const np = normPlate(v.plate);
  const t = (v.type || "").trim();
  for (const c of WEEKLY_COLS) {
    if (c.plates.includes(np)) return c.name;
    if (c.noPlateTypes && (np === "بدون" || np === "") && c.noPlateTypes.includes(t)) return c.name;
  }
  return "اخرى";
}

// ====== المزامنة عبر GitHub (المستودع نفسه قاعدة البيانات) ======
const GH = { owner: "alsubhi1415-dev", repo: "Akram.Su", path: "data.json", branch: "main" };
const GH_API = "https://api.github.com/repos/" + GH.owner + "/" + GH.repo + "/contents/" + GH.path;
const _cid = Math.random().toString(36).slice(2, 10);
const b64enc = (s) => btoa(unescape(encodeURIComponent(s)));
const b64dec = (s) => decodeURIComponent(escape(atob(s.replace(/\n/g, ""))));
// تشفير رمز الربط بمفتاح مشتق من كلمة السر (يفك على جهاز من يملكها فقط)
function xorHex(text, keyHex) {
  let out = "";
  let ks = "";
  let ctr = 0;
  while (ks.length < text.length * 2) { ks += sha256(keyHex + ":" + ctr); ctr++; }
  for (let n = 0; n < text.length; n++) {
    const b = text.charCodeAt(n) ^ parseInt(ks.substr(n * 2, 2), 16);
    out += (b < 16 ? "0" : "") + b.toString(16);
  }
  return out;
}
function xorUnhex(hex, keyHex) {
  try {
    let ks = "";
    let ctr = 0;
    while (ks.length < hex.length) { ks += sha256(keyHex + ":" + ctr); ctr++; }
    let out = "";
    for (let n = 0; n < hex.length / 2; n++) {
      out += String.fromCharCode(parseInt(hex.substr(n * 2, 2), 16) ^ parseInt(ks.substr(n * 2, 2), 16));
    }
    return out;
  } catch { return ""; }
}
const RAW = "https://raw.githubusercontent.com/" + GH.owner + "/" + GH.repo + "/" + GH.branch + "/";
const VER_PATH = "ver.json";
const API_BASE = "https://api.github.com/repos/" + GH.owner + "/" + GH.repo + "/contents/";
// قراءة المؤشر: الواجهة الرسمية أولاً (طازجة دائماً، والـ304 لا يُحتسب)، والخام احتياط عند تجاوز الحصة
// مسار قراءة ثالث: نفس أصل الصفحة.
// ما دامت صفحة البرنامج قد فُتحت فإن ملفات البيانات بجوارها تُقرأ حتماً:
// لا حد استخدام ولا نطاق خارجي قد يُحجب على بعض الشبكات.
const SELF_BASE = (() => {
  try {
    if (typeof window === "undefined" || !window.location) return "";
    const p = window.location.protocol;
    if (p !== "http:" && p !== "https:") return "";
    const href = window.location.href.split("#")[0].split("?")[0];
    return href.replace(/[^/]*$/, "");
  } catch (e) { return ""; }
})();

// سجل تشخيص المزامنة: يُعرض للمستخدم بدل التخمين عند أي عطل
const SYNC = { src: "", tries: [], lastRev: "", lastAt: 0, token: false, push: "", err: "" };
const srcName = (u) => u.indexOf("api.github.com") === 0 || u.indexOf("https://api.github.com") === 0
  ? "الواجهة الرسمية" : (u.indexOf("raw.githubusercontent") >= 0 ? "المسار الاحتياطي" : "نفس أصل الصفحة");

async function fetchFirst(urls) {
  let sawMissing = false;
  for (const u of urls) {
    try {
      const r = await fetch(u, { cache: "no-store" });
      if (r.status === 404) { sawMissing = true; SYNC.tries.push(srcName(u) + ": \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f"); continue; }
      if (!r.ok) { SYNC.tries.push(srcName(u) + ": \u062e\u0637\u0623 " + r.status); continue; }
      SYNC.src = srcName(u);
      SYNC.tries = SYNC.tries.slice(-4);
      return { text: await r.text() };
    } catch (e) {
      SYNC.tries.push(srcName(u) + ": \u062a\u0639\u0630\u0631 \u0627\u0644\u0648\u0635\u0648\u0644");
    }
  }
  SYNC.tries = SYNC.tries.slice(-4);
  if (sawMissing) return { missing: true };
  return null;
}

async function readVer(token, st) {
  // برمز الربط: الواجهة الرسمية أولاً لأنها طازجة لحظياً.
  // بلا رمز: لا تُستعمل إطلاقاً لأن حصتها 60 طلباً في الساعة وتُستنفد في دقائق.
  if (token) {
    try {
      const h = { Accept: "application/vnd.github.raw", Authorization: "Bearer " + token };
      if (st.etagV) h["If-None-Match"] = st.etagV;
      const r = await fetch(API_BASE + VER_PATH + "?ref=" + GH.branch, { headers: h, cache: "no-store" });
      if (r.status === 304) return { unchanged: true };
      if (r.status === 404) return { missing: true };
      if (r.ok) { st.etagV = r.headers.get("ETag"); SYNC.src = "الواجهة الرسمية"; return { fresh: true, ver: JSON.parse(await r.text()) }; }
    } catch (e) {}
  }
  const nc = "?nc=" + Date.now();
  const urls = [];
  if (SELF_BASE) urls.push(SELF_BASE + VER_PATH + nc);
  urls.push(RAW + VER_PATH + nc);
  if (!SELF_BASE) urls.push(API_BASE + VER_PATH + "?ref=" + GH.branch);
  const res = await fetchFirst(urls);
  if (!res) throw new Error("ver-unreachable");
  if (res.missing) return { missing: true };
  return { fresh: false, ver: JSON.parse(res.text) };
}

async function readData(token, wantRev) {
  if (token) {
    try {
      const r = await fetch(API_BASE + GH.path + "?ref=" + GH.branch, {
        headers: { Accept: "application/vnd.github.raw", Authorization: "Bearer " + token }, cache: "no-store",
      });
      if (r.ok) return await r.text();
    } catch (e) {}
  }
  const nc = "?nc=" + encodeURIComponent(wantRev || Date.now());
  const urls = [];
  if (SELF_BASE) urls.push(SELF_BASE + GH.path + nc);
  urls.push(RAW + GH.path + nc);
  if (!SELF_BASE) urls.push(API_BASE + GH.path + "?ref=" + GH.branch);
  const res = await fetchFirst(urls);
  if (!res || res.missing) throw new Error("data-unreachable");
  return res.text;
}
// الكتابة عبر واجهة GitHub الرسمية (برمز الربط)
async function ghGetSha(token, path) {
  const r = await fetch("https://api.github.com/repos/" + GH.owner + "/" + GH.repo + "/contents/" + path + "?ref=" + GH.branch, {
    headers: { Accept: "application/vnd.github+json", Authorization: "Bearer " + token },
  });
  if (r.status === 404) return null;
  if (r.status === 401 || r.status === 403) throw new Error("gh-auth");
  if (!r.ok) throw new Error("gh-sha " + r.status);
  return (await r.json()).sha;
}
// ====== الدمج الثلاثي: يحفظ تعديلات كل المحررين بدل "آخر كتابة تفوز" ======
const _eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
function mergeById(baseArr, mineArr, theirsArr, stats, label) {
  const B = {}, M = {}, T = {};
  (baseArr || []).forEach((x) => (B[x.id] = x));
  (mineArr || []).forEach((x) => (M[x.id] = x));
  (theirsArr || []).forEach((x) => (T[x.id] = x));
  const ids = new Set([...Object.keys(M), ...Object.keys(T)]);
  const out = [];
  ids.forEach((id) => {
    const b = B[id], m = M[id], t = T[id];
    if (m && !t) { if (b && _eq(b, m)) { stats.theirDel++; return; } out.push(m); stats.mineKeep++; return; } // حذفها الزميل ولم أعدّلها
    if (!m && t) { if (b && _eq(b, t)) { stats.mineDel++; return; } out.push(t); stats.theirKeep++; return; } // حذفتها أنا ولم يعدّلها
    if (!m && !t) return;
    if (_eq(m, t)) { out.push(m); return; }
    const mChanged = !b || !_eq(b, m), tChanged = !b || !_eq(b, t);
    if (mChanged && !tChanged) { out.push(m); stats.mine++; return; }
    if (tChanged && !mChanged) { out.push(t); stats.theirs++; return; }
    // تعارض حقيقي على السجل نفسه: الأحدث ختماً يفوز وإلا تعديلي
    const mt = +(m._ts || 0), tt = +(t._ts || 0);
    if (tt > mt) { out.push(t); stats.theirs++; stats.clash.push(label + ": " + (t.plate || t.id)); }
    else { out.push(m); stats.mine++; if (tt || mt) stats.clash.push(label + ": " + (m.plate || m.id)); }
  });
  return out;
}
function mergeMap(base, mine, theirs, stats, depth) {
  const out = {};
  const keys = new Set([...Object.keys(mine || {}), ...Object.keys(theirs || {})]);
  keys.forEach((k) => {
    const b = (base || {})[k], m = (mine || {})[k], t = (theirs || {})[k];
    if (m === undefined && t !== undefined) { out[k] = t; if (!_eq(b, t)) stats.theirs++; return; }
    if (t === undefined && m !== undefined) { out[k] = m; if (!_eq(b, m)) stats.mine++; return; }
    if (_eq(m, t)) { out[k] = m; return; }
    const mCh = !_eq(b, m), tCh = !_eq(b, t);
    if (depth > 0 && m && t && typeof m === "object" && typeof t === "object" && !Array.isArray(m) && !Array.isArray(t)) {
      out[k] = mergeMap(b || {}, m, t, stats, depth - 1); return;
    }
    if (mCh && !tCh) { out[k] = m; stats.mine++; return; }
    if (tCh && !mCh) { out[k] = t; stats.theirs++; return; }
    out[k] = m; stats.mine++; stats.clash.push("جاهزية: " + k);
  });
  return out;
}
function mergeDb(base, mine, theirs) {
  base = base || {}; mine = mine || {}; theirs = theirs || {};
  const stats = { mine: 0, theirs: 0, mineKeep: 0, theirKeep: 0, mineDel: 0, theirDel: 0, clash: [] };
  const uniq = (a) => { const s = new Set(); return a.filter((x) => { const k = JSON.stringify(x); if (s.has(k)) return false; s.add(k); return true; }); };
  const out = {
    ...theirs, ...mine,
    vehicles: mergeById(base.vehicles, mine.vehicles, theirs.vehicles, stats, "آلية"),
    incidents: mergeById(base.incidents, mine.incidents, theirs.incidents, stats, "حادث"),
    centerReadiness: mergeMap(base.centerReadiness, mine.centerReadiness, theirs.centerReadiness, stats, 1),
    equipReadiness: mergeMap(base.equipReadiness, mine.equipReadiness, theirs.equipReadiness, stats, 2),
    supportReadiness: mergeMap(base.supportReadiness, mine.supportReadiness, theirs.supportReadiness, stats, 1),
    opsMeta: { ...(theirs.opsMeta || {}), ...(mine.opsMeta || {}) },
    rdyHist: { ...(theirs.rdyHist || {}), ...(mine.rdyHist || {}) },
    cohort186: (() => {
      const a = mine.cohort186, b = theirs.cohort186;
      if (!a) return b; if (!b) return a;
      const ai = a.items || {}, bi = b.items || {}, out = {};
      new Set([...Object.keys(ai), ...Object.keys(bi)]).forEach((k) => {
        const x = ai[k], y = bi[k];
        if (!x) { out[k] = y; return; }
        if (!y) { out[k] = x; return; }
        out[k] = (+(y.at || 0) > +(x.at || 0)) ? y : x; // الأحدث قراراً يفوز
      });
      return { ...b, ...a, items: out };
    })(),
    trash: uniq([...(theirs.trash || []), ...(mine.trash || [])]).slice(-300),
    archive: uniq([...(theirs.archive || []), ...(mine.archive || [])]).slice(-52),
    audit: uniq([...(theirs.audit || []), ...(mine.audit || [])]).slice(-500),
  };
  return { merged: out, stats };
}

async function ghGetJson(token, path) {
  const r = await fetch("https://api.github.com/repos/" + GH.owner + "/" + GH.repo + "/contents/" + path + "?ref=" + GH.branch, {
    headers: { Accept: "application/vnd.github.raw+json", Authorization: "Bearer " + token },
  });
  if (!r.ok) throw new Error("gh-json " + r.status);
  return await r.json();
}
async function ghPutFile(token, path, text, sha, msg) {
  const body = { message: msg, content: b64enc(text), branch: GH.branch };
  if (sha) body.sha = sha;
  const r = await fetch("https://api.github.com/repos/" + GH.owner + "/" + GH.repo + "/contents/" + path, {
    method: "PUT",
    headers: { Accept: "application/vnd.github+json", Authorization: "Bearer " + token, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (r.status === 401 || r.status === 403) throw new Error("gh-auth");
  if (r.status === 409 || r.status === 422) throw new Error("gh-conflict");
  if (!r.ok) throw new Error("gh-write " + r.status);
  const j = await r.json();
  return j.content && j.content.sha;
}
