function unifyUnit(u) {
  const s = normU(u);
  if (!s) return "غير محدد";
  for (const r of BRANCH_RULES) {
    if (r.test.some((t) => s.includes(t))) {
      return r.name === "__self__" ? (u || "").replace(/\s+/g, " ").trim() : r.name;
    }
  }
  return (u || "").replace(/\s+/g, " ").trim();
}
