const emptyVehicle = () => ({
  id: "v_" + Date.now() + "_" + Math.floor(Math.random() * 9999),
  type: "", plate: "", unit: "", itemNo: "", chassis: "",
  color: "", model: "", location: "", status: "تعمل", notes: "",
  faults: [], transfers: [],
  createdAt: new Date().toISOString().slice(0, 10),
});

const fmtDate = (d) => (d ? d : "—");

// ====== التقويم الهجري ======
const HIJRI_MONTHS = [
  "محرم", "صفر", "ربيع الأول", "ربيع الآخر", "جمادى الأولى", "جمادى الآخرة",
  "رجب", "شعبان", "رمضان", "شوال", "ذو القعدة", "ذو الحجة",
];

function todayHijri() {
  try {
    const parts = new Intl.DateTimeFormat("en-u-ca-islamic-umalqura", {
      day: "numeric", month: "numeric", year: "numeric",
    }).formatToParts(new Date());
    const get = (t) => parts.find((p) => p.type === t)?.value;
    return { d: parseInt(get("day")), m: parseInt(get("month")), y: parseInt(get("year")) };
  } catch { return { d: 1, m: 1, y: 1448 }; }
}

// القيمة تُخزَّن بصيغة "1448/01/22" لتسهيل الترتيب الزمني
function hijriDisplay(str) {
  if (!str) return "—";
  const [y, m, d] = str.split("/").map((x) => parseInt(x));
  if (!y || !m || !d) return str;
  return `${d} ${HIJRI_MONTHS[m - 1] || m} ${y}هـ`;
}

function HijriDateInput({ value, onChange, required }) {
  const t = todayHijri();
  const parsed = value ? value.split("/").map((x) => parseInt(x)) : [];
  const [y, m, d] = [parsed[0] || "", parsed[1] || "", parsed[2] || ""];

  // الحقول الإلزامية تبدأ بتاريخ اليوم الهجري تلقائياً
  useEffect(() => {
    if (required && !value) {
      onChange(`${t.y}/${String(t.m).padStart(2, "0")}/${String(t.d).padStart(2, "0")}`);
    }
  }, []);

  const emit = (ny, nm, nd) => {
    if (ny && nm && nd) onChange(`${ny}/${String(nm).padStart(2, "0")}/${String(nd).padStart(2, "0")}`);
    else onChange("");
  };
  const years = [];
  for (let yy = t.y + 1; yy >= t.y - 20; yy--) years.push(yy);
  const selStyle = { ...inputStyle, padding: "10px 6px", flex: 1, minWidth: 0 };

  return (
    <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
      <select style={selStyle} value={d} onChange={(e) => emit(y || t.y, m || t.m, parseInt(e.target.value) || "")}>
        <option value="">اليوم</option>
        {Array.from({ length: 30 }, (_, i) => i + 1).map((dd) => <option key={dd} value={dd}>{dd}</option>)}
      </select>
      <select style={{ ...selStyle, flex: 1.6 }} value={m} onChange={(e) => emit(y || t.y, parseInt(e.target.value) || "", d || t.d)}>
        <option value="">الشهر</option>
        {HIJRI_MONTHS.map((name, i) => <option key={name} value={i + 1}>{name}</option>)}
      </select>
      <select style={selStyle} value={y} onChange={(e) => emit(parseInt(e.target.value) || "", m || t.m, d || t.d)}>
        <option value="">السنة</option>
        {years.map((yy) => <option key={yy} value={yy}>{yy}هـ</option>)}
      </select>
      {!required && value && (
        <button onClick={() => onChange("")} title="مسح التاريخ" style={{ background: "none", border: "none", color: "#8B93A3", cursor: "pointer", fontSize: 15, fontFamily: "inherit", padding: 2 }}>✕</button>
      )}
    </div>
  );
}

// وسيط آمن: window.storage متوفر داخل بيئة الآرتيفاكت فقط، وغير موجود في الملف المستقل ولا في النسخة المنشورة
const hasStore = () => { try { return typeof window !== "undefined" && !!window.storage && typeof window.storage.get === "function"; } catch (e) { return false; } };
const stGet = async (k) => { if (!hasStore()) return null; try { return await window.storage.get(k); } catch (e) { return null; } };
const stSet = async (k, v) => { if (!hasStore()) return false; try { await window.storage.set(k, v); return true; } catch (e) { return false; } };

// ====== المرآة المحلية ======
// تُحفظ آخر نسخة سحابية مُستلمة على الجهاز، فيرى المستخدم آخر موقف حقيقي
// حتى لو انقطعت الشبكة تماماً — بدل بيانات الإكسل المحقونة وقت البناء.
const MIRROR_KEY = "fd_mirror_v1";
// طابور الرفع: أي تعديل لم يصل السحابة يبقى محفوظاً على الجهاز حتى ينجح رفعه
const PENDING_KEY = "fd_pending_v1";
function pendingRead() {
  try { const r = localStorage.getItem(PENDING_KEY); if (!r) return null;
    const p = JSON.parse(r);
    return (p && p.db && Array.isArray(p.db.vehicles) && p.db.vehicles.length > 0) ? p : null;
  } catch (e) { return null; }
}
function pendingWrite(db) { try { localStorage.setItem(PENDING_KEY, JSON.stringify({ db, at: Date.now() })); return true; } catch (e) { return false; } }
function pendingClear() { try { localStorage.removeItem(PENDING_KEY); } catch (e) {} }
function mirrorRead() {
  try {
    const raw = localStorage.getItem(MIRROR_KEY);
    if (!raw) return null;
    const m = JSON.parse(raw);
    if (m && m.db && Array.isArray(m.db.vehicles) && m.db.vehicles.length > 0) return m;
  } catch (e) {}
  return null;
}
function mirrorWrite(db, rev, cfg) {
  try {
    // إن لم يُمرّر مؤشر أو إعدادات فيُحافظ على المحفوظ بدل محوه
    const prev = mirrorRead();
    const keep = rev || (prev && prev.rev) || "";
    const kcfg = cfg || (prev && prev.cfg) || null;
    localStorage.setItem(MIRROR_KEY, JSON.stringify({ rev: keep, at: Date.now(), db, cfg: kcfg }));
    return true;
  } catch (e) { return false; } // تجاوز سعة التخزين: يُتجاهل بلا إزعاج
}

// ====== تلخيص التغيير: ماذا تبدّل بين نسختين من قاعدة البيانات ======
function summarizeChange(base, next) {
  try {
    const B = base || {}, N = next || {};
    const bv = {}, nv = {};
    (B.vehicles || []).forEach((v) => { bv[v.id] = v; });
    (N.vehicles || []).forEach((v) => { nv[v.id] = v; });
    const added = [], removed = [], changed = [];
    Object.keys(nv).forEach((id) => {
      if (!bv[id]) added.push(nv[id]);
      else if (JSON.stringify(bv[id]) !== JSON.stringify(nv[id])) changed.push(nv[id]);
    });
    Object.keys(bv).forEach((id) => { if (!nv[id]) removed.push(bv[id]); });
    const cnt = (o) => (o.vehicles || []).reduce((a, v) => a + ((v.faults || []).length), 0);
    const df = cnt(N) - cnt(B);
    const di = ((N.incidents || []).length) - ((B.incidents || []).length);
    const dr = Object.keys(N.rdyHist || {}).length - Object.keys(B.rdyHist || {}).length;
    const rdyChanged = JSON.stringify(B.centerReadiness || {}) !== JSON.stringify(N.centerReadiness || {});
    const eqChanged = JSON.stringify(B.equipReadiness || {}) !== JSON.stringify(N.equipReadiness || {})
      || JSON.stringify(B.supportReadiness || {}) !== JSON.stringify(N.supportReadiness || {});
    const parts = [];
    if (added.length) parts.push("إضافة " + added.length + " آلية");
    if (removed.length) parts.push("حذف " + removed.length + " آلية");
    if (changed.length) parts.push("تعديل " + changed.length + " آلية");
    if (df > 0) parts.push("تسجيل " + df + " عطل");
    if (df < 0) parts.push("إزالة " + (-df) + " عطل");
    if (di > 0) parts.push("تسجيل " + di + " حادث");
    if (dr > 0) parts.push("لقطة جاهزية جديدة");
    if (rdyChanged) parts.push("تحديث جاهزية المراكز");
    if (eqChanged) parts.push("تحديث جاهزية المعدات والإسناد");
    const plates = [...changed, ...added].map((v) => v.plate).filter(Boolean).slice(0, 3);
    return { txt: parts.length ? parts.join(" · ") : "تحديث بيانات", plates };
  } catch (e) { return { txt: "تحديث بيانات", plates: [] }; }
}

async function loadDB() {
  // الأولوية للمرآة المحلية (آخر نسخة سحابية حقيقية)، ثم التخزين القديم،
  // ولا يُلجأ لبيانات الإكسل إلا في أول زيارة على الإطلاق.
  const m = mirrorRead();
  if (m) return { db: m.db, rev: m.rev || "", cfg: m.cfg || null, from: "mirror" };
  try {
    const r = await stGet(STORAGE_KEY);
    if (r) {
      const db = JSON.parse(r.value);
      if (db && Array.isArray(db.vehicles) && db.vehicles.length > 0) return { db, rev: "", from: "legacy" };
    }
  } catch {}
  return { db: { vehicles: SEED_DB.vehicles }, rev: "", from: "seed" };
}
async function saveDB(db, rev, cfg) {
  mirrorWrite(db, rev, cfg);
  await stSet(STORAGE_KEY, JSON.stringify(db));
}

